def add(a,b):return [x+y for x,y in zip(a,b)]
def sub(a,b):return [x-y for x,y in zip(a,b)]
def mul(a,t):return [x*t for x in a]
def lerp(a,b,t):return add(a,mul(sub(b,a),t))
def cross(a,b):return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]
def dot(a,b):return sum(x*y for x,y in zip(a,b))
def norm(a):return math.sqrt(dot(a,a))
def V(label,segs=None,poly=None,pts=None):
 d={'label':label}
 if segs:d['segments']=segs
 if poly:d['polygon']=poly
 if pts:d['points']=pts
 return d

def G(p,e=None,f=None,v=None,names=None,planar=False):
 d={'points':p,'edges':e or [],'views':{'neutral':V('Условие задачи'),**(v or {})},'labelNames':list(p) if names is None else names}
 if f:d['faces']=f
 if planar:d['planar']=True
 labels={k:k[0]+'₁' for k in p if len(k)==2 and k.endswith('1') and k[0].isupper()}
 if labels:d['labels']=labels
 return d

def cube(x=4,y=4,z=4):
 p={'A':[0,0,0],'B':[0,y,0],'C':[x,y,0],'D':[x,0,0],'A1':[0,0,z],'B1':[0,y,z],'C1':[x,y,z],'D1':[x,0,z]}
 e=[['A','B'],['B','C'],['C','D'],['D','A'],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1']]
 f=[['A','D','C','B'],['A1','B1','C1','D1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','D','D1','C1'],['D','A','A1','D1']]
 return p,e,f

def tetra(regular=None):
 if regular:
  a=regular;p={'A':[0,0,0],'B':[a,0,0],'C':[a/2,a*math.sqrt(3)/2,0],'D':[a/2,a*math.sqrt(3)/6,a*math.sqrt(2/3)]}
 else:p={'A':[-2,-1,0],'B':[2,-1,0],'C':[1,3,0],'D':[0,0,4]}
 e=[['A','B'],['A','C'],['B','C'],['D','A'],['D','B'],['D','C']];f=[['A','C','B'],['A','B','D'],['B','C','D'],['C','A','D']]
 return p,e,f

def plane(p,z=0,size=4,prefix='p'):
 keys=[prefix+str(i) for i in range(4)];p.update(dict(zip(keys,[[-size,-size,z],[size,-size,z],[size,size,z],[-size,size,z]])));return keys

def S(title,text,why,view='neutral',prompt=None):return {'title':title,'prompt':prompt or title+'. Объясни свой выбор.','explanation':text,'justifications':[{'kind':'theorem','text':why}],'view':view}

def card(sec,n,title,text,goal,g,steps,hint,parts=None,subpart=None,pages=None,caption=CAP):
 number=f'{sec}.{n}';source0=SOURCES[number];src={k:copy.deepcopy(source0['source'][k]) for k in ['bookId','collection','exercise','chapter','printedPages','pdfPages']}
 if pages:src['printedPages']=pages;src['pdfPages']=[p+1 for p in pages]
 suffix='-'+subpart if subpart else '';identifier=f'merz-ex-{sec:02}-{n:03}'+suffix;file=f'ex-{sec:02}-{n:03}'+suffix+'.json'
 if subpart:src['subpart']=subpart
 for i,s in enumerate(steps,1):s['id']=f'step-{i}'
 d={'schemaVersion':1,'revision':1,'id':identifier,'kind':'exercise','title':number+('('+subpart+')' if subpart else '')+'. '+title,'status':'draft','source':src,'statement':{'text':text,'goal':goal},'visualization':{'type':'scene3d','caption':caption,'model':g},'help':[{'id':'help-1','question':hint[0],'text':hint[1]}],'steps':steps,'answer':{'mode':'manual','prompt':'Запиши ответ, ход построения или доказательство. Рассуждение сохраняется для обсуждения с преподавателем и автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 (OUT/file).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 c=next((c for c in coverage if c['exercise']==number),None)
 if not c:
  c={'sourceEntryId':source0['id'],'exercise':number,'requiredParts':[],'textbookParts':parts or [],'sourcePdfPages':[],'lessonFiles':[]};coverage.append(c)
 c['requiredParts'].append(subpart);c['sourcePdfPages']=sorted(set(c['sourcePdfPages']+src['pdfPages']));c['lessonFiles'].append('stereo-course/merzlyak-10-base/lessons/'+file)

