card(4,5,'Проверка четырёх утверждений','Верно ли: 1) непараллельные прямые имеют общую точку; 2) нескрещивающиеся прямые лежат в одной плоскости; 3) прямые одной плоскости пересекаются; 4) непересекающиеся и непараллельные прямые скрещиваются?','Обосновать верные утверждения и привести контрпримеры к неверным.',G(p,e,f,{'skew':V('AA₁ и BC скрещиваются',[['A','A1'],['B','C']]),'parallel':V('AB и CD параллельны',[['A','B'],['C','D']])}),[S('Утверждение 1','Неверно. AA₁ и BC в кубе не параллельны, но общей точки не имеют.','Контрпример: скрещивающиеся прямые.','skew'),S('Утверждение 2','Верно. Скрещивающимися называют именно прямые, не лежащие в одной плоскости. Отрицание этого свойства означает наличие общей плоскости.',SKEW),S('Утверждение 3','Неверно. AB и CD лежат в плоскости основания куба и параллельны.','Контрпример: параллельные прямые.','parallel'),S('Утверждение 4','Верно для двух различных прямых: в одной плоскости непересекающиеся прямые были бы параллельны. Раз это исключено, общей плоскости нет.',PAR+' '+SKEW,'skew')],('Как проверять утверждение «для любых прямых»?','Для опровержения достаточно одного контрпримера; для подтверждения нужна общая аргументация.'),parts=list('1234'))
