card(5,41,'Площадь прямоугольной трапеции','Боковые стороны прямоугольной трапеции относятся как 3:5, основания отличаются на 16 см, меньшая диагональ равна 13 см. Найдите площадь трапеции.','Последовательно найти высоту, основания и площадь.',G(p,[['A','B'],['B','C'],['C','D'],['D','A'],['A','C']],v={'height':V('Прямоугольный треугольник CHD',[['C','H']],['C','H','D']),'diagonal':V('Меньшая диагональ AC',[['A','C']],['A','B','C']),'area':V('Трапеция ABCD',poly=['A','B','C','D'])},names=list('ABCD'),planar=True),[S('Обозначь боковые стороны','Пусть высота AB=3x, наклонная сторона CD=5x. Опустим CH⊥AD. Тогда CH=3x, HD=AD−BC=16.','Свойства прямоугольной трапеции.','height'),S('Найди высоту','В CHD: (5x)²=(3x)²+16². Отсюда 16x²=256, x=4, высота h=12 см.','Теорема Пифагора.','height'),S('Найди основания','Меньшая диагональ соединяет вершины при меньшем основании: AC²=AB²+BC². Поэтому BC=√(13²−12²)=5 см. AD=5+16=21 см.','Теорема Пифагора.','diagonal'),S('Вычисли площадь','S=(AD+BC)·h/2=(21+5)·12/2=156 см². Ответ: 156 см².','Формула площади трапеции.','area')],('Почему отношение сторон 3:5 относится к высоте и наклонной стороне именно так?','Высота — катет прямоугольного треугольника, а наклонная боковая сторона — его гипотенуза, поэтому она длиннее.'))
